// ecdsaRawToDER converts a fixed-width r||s PKCS#11 ECDSA signature into
// the ASN.1 DER form that crypto/tls and crypto/x509 verifiers expect.
func ecdsaRawToDER(raw []byte) ([]byte, error) {
	if len(raw) == 0 || len(raw)%2 != 0 {
		return nil, fmt.Errorf("pkcs11: bad ECDSA signature length %d", len(raw))
	}
	half := len(raw) / 2
	var sig struct{ R, S *big.Int }
	sig.R = new(big.Int).SetBytes(raw[:half])
	sig.S = new(big.Int).SetBytes(raw[half:])
	return asn1.Marshal(sig)
}

